          vapour+=mistBank(eye,aim,reach,vec3(-365.,21.+4.*flooded,111.)+drift*.73,
            vec3(263.,31.,164.))*.0022;
          vapour+=mistBank(eye,aim,reach,vec3(-83.,-7.+11.*flooded,-45.)+drift*.62,
            vec3(206.,15.,84.))*.0069;
